package local.shiguang.album;
import android.content.*;import android.content.pm.*;import android.net.Uri;import android.provider.Settings;import org.json.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;
final class AppUpdater {
 final MainActivity activity;String url,digest,version;
 AppUpdater(MainActivity a){activity=a;}
 static int compare(String a,String b){String[] x=a.split("\\."),y=b.split("\\.");for(int i=0;i<3;i++){int d=Integer.parseInt(x[i])-Integer.parseInt(y[i]);if(d!=0)return d;}return 0;}
 HttpURLConnection connect(String address)throws Exception{URL u=new URL(address);for(int i=0;i<8;i++){String host=u.getHost();if(!"https".equals(u.getProtocol())||!(host.equals("api.github.com")||host.equals("github.com")||host.equals("release-assets.githubusercontent.com")||host.equals("objects.githubusercontent.com")))throw new IOException("更新地址不受信任");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(20000);c.setReadTimeout(60000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Shiguang-Universal-Updater");int code=c.getResponseCode();if(code>=300&&code<400){String next=c.getHeaderField("Location");c.disconnect();u=new URL(u,next);continue;}if(code!=200){c.disconnect();throw new IOException("GitHub 请求失败："+code);}return c;}throw new IOException("更新地址重定向过多");}
 JSONObject check()throws Exception{url=null;digest=null;String current=activity.getPackageManager().getPackageInfo(activity.getPackageName(),0).versionName;String best=current;HttpURLConnection c=connect("https://api.github.com/repos/fei33fei/shiguang/releases?per_page=100");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))>0){if(out.size()+n>8000000)throw new IOException("版本列表过大");out.write(b,0,n);}}finally{c.disconnect();}JSONArray releases=new JSONArray(out.toString("UTF-8"));for(int i=0;i<releases.length();i++){JSONObject release=releases.getJSONObject(i);if(release.optBoolean("draft"))continue;JSONArray assets=release.getJSONArray("assets");for(int j=0;j<assets.length();j++){JSONObject asset=assets.getJSONObject(j);String name=asset.getString("name");java.util.regex.Matcher m=java.util.regex.Pattern.compile("Shiguang-Android-([0-9]+\\.[0-9]+\\.[0-9]+)-universal\\.apk").matcher(name);if(m.matches()&&compare(m.group(1),best)>0){String hash=asset.optString("digest");if(!hash.matches("sha256:[0-9a-f]{64}"))continue;best=m.group(1);url=asset.getString("browser_download_url");digest=hash.substring(7);}}}version=best;return new JSONObject().put("current",current).put("version",best).put("available",url!=null);}
 void install()throws Exception{if(url==null)throw new IOException("请先检查更新");File file=new File(activity.getCacheDir(),"update.apk");HttpURLConnection c=connect(url);MessageDigest sha=MessageDigest.getInstance("SHA-256");try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(file)){byte[] b=new byte[65536];int n;long size=0;while((n=in.read(b))>0){size+=n;if(size>150000000)throw new IOException("安装包过大");sha.update(b,0,n);out.write(b,0,n);}}finally{c.disconnect();}StringBuilder hash=new StringBuilder();for(byte b:sha.digest())hash.append(String.format("%02x",b&255));if(!hash.toString().equals(digest)){file.delete();throw new IOException("下载校验失败，请重试");}PackageManager pm=activity.getPackageManager();PackageInfo archive=pm.getPackageArchiveInfo(file.getPath(),PackageManager.GET_SIGNING_CERTIFICATES),local=pm.getPackageInfo(activity.getPackageName(),PackageManager.GET_SIGNING_CERTIFICATES);if(archive==null||!local.packageName.equals(archive.packageName)||archive.getLongVersionCode()<=local.getLongVersionCode()||!Arrays.equals(local.signingInfo.getApkContentsSigners(),archive.signingInfo.getApkContentsSigners())){file.delete();throw new IOException("包名、版本或签名不匹配，已停止安装");}activity.runOnUiThread(()->{try{if(!pm.canRequestPackageInstalls())activity.startActivityForResult(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())),110);else launch();}catch(Exception e){android.widget.Toast.makeText(activity,"请允许拾光安装更新后重试",1).show();}});}
 void launch(){Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse("content://local.shiguang.album.updates/update.apk"),"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);activity.startActivity(intent);}
}
